def solve(inp):
    h,w=len(inp),len(inp[0])
    # find period p of diagonal stripes (j-i) mod p consistent with input
    for p in range(1,w+1):
        c={}
        ok=True
        for i in range(h):
            for j in range(w):
                v=inp[i][j]
                if v:
                    r=(j-i)%p
                    if r in c and c[r]!=v: ok=False; break
                    c[r]=v
            if not ok: break
        if ok and len(c)==p:
            # fill
            return [[c[(j-i)%p] for j in range(w)] for i in range(h)]
